import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, readFile, rm, mkdir, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
const profile = await mkdtemp(path.join(os.tmpdir(), 'legendgirl-som-chrome-'));
const chrome = spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', ['--headless=new', '--mute-audio', '--no-first-run', '--no-default-browser-check', '--autoplay-policy=no-user-gesture-required', '--remote-debugging-port=0', '--user-data-dir='+profile, 'about:blank'], {stdio:'ignore'});
let ws;
try {
 let port;
 for(let i=0;i<100;i++) { try { port=(await readFile(path.join(profile,'DevToolsActivePort'),'utf8')).split('\n')[0];break; } catch {} await new Promise(r=>setTimeout(r,100)); }
 assert.ok(port,'Chrome de QA inicializado');
 const tabs=await (await fetch('http://127.0.0.1:'+port+'/json/list')).json();
 ws=new WebSocket(tabs.find(t=>t.type==='page').webSocketDebuggerUrl);
 await new Promise(r=>ws.onopen=r);
 let id=0;const pending=new Map();ws.onmessage=e=>{const d=JSON.parse(e.data);if(d.id){pending.get(d.id)?.(d);pending.delete(d.id);}};
 const call=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}));});
 const evaluate=async expression=>{const r=await call('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(r.result?.exceptionDetails)throw Error(JSON.stringify(r.result.exceptionDetails));return r.result?.result?.value;};

 const output='docs/diario-ia/qa-resultados/contato-integral';await mkdir(output,{recursive:true});
 const reports=[];
 for(const [name,width,height,mobile]of [['desktop',960,540,false],['android',390,844,true],['android-paisagem',844,390,true],['iphone',390,844,true]]){
  await call('Emulation.setDeviceMetricsOverride',{width,height,deviceScaleFactor:1,mobile});await call('Emulation.setTouchEmulationEnabled',{enabled:mobile});
  await call('Emulation.setUserAgentOverride',{userAgent:mobile?(name==='iphone'?'Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) Mobile':'Mozilla/5.0 (Linux; Android 14) Mobile'):'Mozilla/5.0 (Macintosh)'});
  await call('Page.navigate',{url:'http://127.0.0.1:3000/tests/dark-room-playthrough.html'});
  let ready=false;for(let i=0;i<300;i++){if(await evaluate('Boolean(window.review)')){ready=true;break;}await new Promise(r=>setTimeout(r,100));}assert.ok(ready,'Jogo de produção carregado');
  await evaluate(`(async()=>{window.qa=await import('/docs/diario-ia/qa/contato-integral-20261023/cenario.js');})()`);
  const geometry=await evaluate('qa.geometry()');
  const routes=name==='desktop'?await evaluate('qa.routes()'):[];
  const inputs=[];
  for(const [index,x,phase3]of [[0,355,false],[1,387,false],[3,804,false],[6,1260,false],[5,2825,true]]){
   const before=await evaluate(`qa.prepareInput(${index},${x},${phase3})`);
   if(mobile){await call('Input.dispatchTouchEvent',{type:'touchStart',touchPoints:[{id:1,x:150,y:150}]});await call('Input.dispatchTouchEvent',{type:'touchEnd',touchPoints:[]});}
   else {await call('Input.dispatchKeyEvent',{type:'keyDown',code:'Space',key:' ',windowsVirtualKeyCode:32});await call('Input.dispatchKeyEvent',{type:'keyUp',code:'Space',key:' ',windowsVirtualKeyCode:32});}
   const after=await evaluate('({...review.game.state.baby})');assert.equal(after.onGround,false,'Teclado/toque aceito na borda '+name+'/'+index);assert.ok(after.vy<0);inputs.push({index,phase3,before,after});
  }
  for(const [phase3,index]of [[false,0],[false,4],[false,6],[false,9],[true,5]]){
   await evaluate(`qa.scene(${index},${phase3})`);const data=await evaluate("document.querySelector('canvas').toDataURL().split(',')[1]");const bytes=Buffer.from(data,'base64');await writeFile(output+'/'+name+'-'+phase3+'-'+index+'.png',bytes);if(!mobile)await writeFile('/tmp/legendgirl-contato-'+index+'-'+phase3+'.png',bytes);
  }
  reports.push({name,geometry,routes,inputs});
 }
 await writeFile(output+'/resultado.json',JSON.stringify(reports,null,2));console.log(JSON.stringify(reports.map(r=>({perfil:r.name,contatos:r.geometry.checks,quadrosUniao:r.geometry.walkingFrames,saltos:r.routes.length,entradas:r.inputs.length,apoios:r.geometry.rows})),null,2));
 console.log('APROVADO: contornos reais de 38 apoios, união contínua, travessias preparadas e entradas reais de teclado/toque. Emulação não equivale a certificação em aparelho físico.');
} finally {ws?.close();chrome.kill();await new Promise(r=>chrome.once('exit',r));await rm(profile,{recursive:true,force:true});}
